   580  int next_filter(const uint8_t* filters, int current_filter, char cmode) {
   581    for (int i = current_filter - 1; i >= 0; i--) {
   582      if (!do_nothing(filters[i], cmode)) {
   583        return filters[i];
   584      }
   585    }
   586    return BLOSC_NOFILTER;
   587  }
