   601  uint8_t* pipeline_c(struct thread_context* thread_context, const int32_t bsize,
   602                      const uint8_t* src, const int32_t offset,
   603                      uint8_t* dest, uint8_t* tmp, uint8_t* tmp2) {
   604    blosc2_context* context = thread_context->parent_context;
   605    uint8_t* _src = (uint8_t*)src + offset;
   606    uint8_t* _tmp = tmp;
   607    uint8_t* _dest = dest;
   608    int32_t typesize = context->typesize;
   609    uint8_t* filters = context->filters;
   610    uint8_t* filters_meta = context->filters_meta;
   611    bool memcpyed = context->header_flags & (uint8_t)BLOSC_MEMCPYED;
   612
   613    /* Prefilter function */
   614    if (context->prefilter != NULL) {
   615      // Create new prefilter parameters for this block (must be private for each thread)
   616      blosc2_prefilter_params pparams;
   617      memcpy(&pparams, context->pparams, sizeof(pparams));
   618      pparams.out = _dest;
   619      pparams.out_size = (size_t)bsize;
   620      pparams.out_typesize = typesize;
   621      pparams.out_offset = offset;
   622      pparams.tid = thread_context->tid;
   623      pparams.ttmp = thread_context->tmp;
   624      pparams.ttmp_nbytes = thread_context->tmp_nbytes;
   625      pparams.ctx = context;
   626
   627      if (context->prefilter(&pparams) != 0) {
   628        BLOSC_TRACE_ERROR("Execution of prefilter function failed");
   629        return NULL;
   630      }
   631
   632      if (memcpyed) {
   633        // No more filters are required
   634        return _dest;
   635      }
   636      // Cycle buffers
   637      _src = _dest;
   638      _dest = _tmp;
   639      _tmp = _src;
   640    }
   641
   642    /* Process the filter pipeline */
   643    for (int i = 0; i < BLOSC2_MAX_FILTERS; i++) {
   644      switch (filters[i]) {
   645        case BLOSC_SHUFFLE:
   646          for (int j = 0; j <= filters_meta[i]; j++) {
   647            shuffle(typesize, bsize, _src, _dest);
   648            // Cycle filters when required
   649            if (j < filters_meta[i]) {
   650              _src = _dest;
   651              _dest = _tmp;
   652              _tmp = _src;
   653            }
   654          }
   655          break;
   656        case BLOSC_BITSHUFFLE:
   657          bitshuffle(typesize, bsize, _src, _dest, tmp2);
   658          break;
   659        case BLOSC_DELTA:
   660          delta_encoder(src, offset, bsize, typesize, _src, _dest);
   661          break;
   662        case BLOSC_TRUNC_PREC:
   663          truncate_precision(filters_meta[i], typesize, bsize, _src, _dest);
   664          break;
   665        default:
   666          if (filters[i] != BLOSC_NOFILTER) {
   667            BLOSC_TRACE_ERROR("Filter %d not handled during compression\n", filters[i]);
   668            return NULL;
   669          }
   670      }
   671      // Cycle buffers when required
   672      if (filters[i] != BLOSC_NOFILTER) {
   673        _src = _dest;
   674        _dest = _tmp;
   675        _tmp = _src;
   676      }
   677    }
   678    return _src;
   679  }
