   708  /* Shuffle & compress a single block */
   709  static int blosc_c(struct thread_context* thread_context, int32_t bsize,
   710                     int32_t leftoverblock, int32_t ntbytes, int32_t destsize,
   711                     const uint8_t* src, const int32_t offset, uint8_t* dest,
   712                     uint8_t* tmp, uint8_t* tmp2) {
   713    blosc2_context* context = thread_context->parent_context;
   714    int dont_split = (context->header_flags & 0x10) >> 4;
   715    int dict_training = context->use_dict && context->dict_cdict == NULL;
   716    int32_t j, neblock, nstreams;
   717    int32_t cbytes;                   /* number of compressed bytes in split */
   718    int32_t ctbytes = 0;              /* number of compressed bytes in block */
   719    int64_t maxout;
   720    int32_t typesize = context->typesize;
   721    const char* compname;
   722    int accel;
   723    const uint8_t* _src;
   724    uint8_t *_tmp = tmp, *_tmp2 = tmp2;
   725    uint8_t *_tmp3 = thread_context->tmp4;
   726    int last_filter_index = last_filter(context->filters, 'c');
   727    bool memcpyed = context->header_flags & (uint8_t)BLOSC_MEMCPYED;
   728
   729    if (last_filter_index >= 0 || context->prefilter != NULL) {
   730      /* Apply the filter pipeline just for the prefilter */
   731      if (memcpyed && context->prefilter != NULL) {
   732        // We only need the prefilter output
   733        _src = pipeline_c(thread_context, bsize, src, offset, dest, _tmp2, _tmp3);
   734
   735        if (_src == NULL) {
   736          return -9;  // signals a problem with the filter pipeline
   737        }
   738        return bsize;
   739      }
   740      /* Apply regular filter pipeline */
   741      _src = pipeline_c(thread_context, bsize, src, offset, _tmp, _tmp2, _tmp3);
   742
   743      if (_src == NULL) {
   744        return -9;  // signals a problem with the filter pipeline
   745      }
   746    } else {
   747      _src = src + offset;
   748    }
   749
   750    assert(context->clevel > 0);
   751
   752    /* Calculate acceleration for different compressors */
   753    accel = get_accel(context);
   754
   755    /* The number of compressed data streams for this block */
   756    if (!dont_split && !leftoverblock && !dict_training) {
   757      nstreams = (int32_t)typesize;
   758    }
   759    else {
   760      nstreams = 1;
   761    }
   762    neblock = bsize / nstreams;
   763    for (j = 0; j < nstreams; j++) {
   764      if (!dict_training) {
   765        dest += sizeof(int32_t);
   766        ntbytes += sizeof(int32_t);
   767        ctbytes += sizeof(int32_t);
   768
   769        // See whether we have a run here
   770        const uint8_t* ip = (uint8_t*)_src + j * neblock;
   771        const uint8_t* ipbound = (uint8_t*)_src + (j + 1) * neblock;
   772        if (get_run(ip, ipbound)) {
   773          // A run
   774          int32_t value = _src[j * neblock];
   775          if (ntbytes > destsize) {
   776            /* Not enough space to write out compressed block size */
   777            return -1;
   778          }
   779          // Encode the repeated byte in the first (LSB) byte of the length of the split.
   780          _sw32(dest - 4, -value);    // write the value in two's complement
   781          if (value > 0) {
   782            // Mark the encoding as a run-length (== 0 is always a 0's run)
   783            ntbytes += 1;
   784            ctbytes += 1;
   785            if (ntbytes > destsize) {
   786              /* Not enough space to write out compressed block size */
   787              return -1;
   788            }
   789            // Set MSB bit (sign) to 1 (not really necessary here, but for demonstration purposes)
   790            // dest[-1] |= 0x80;
   791            dest[0] = 0x1;   // set run-length bit (0) in token
   792            dest += 1;
   793          }
   794          continue;
   795        }
   796      }
   797
   798      maxout = neblock;
   799    #if defined(HAVE_SNAPPY)
   800      if (context->compcode == BLOSC_SNAPPY) {
   801        maxout = (int32_t)snappy_max_compressed_length((size_t)neblock);
   802      }
   803    #endif /*  HAVE_SNAPPY */
   804      if (ntbytes + maxout > destsize) {
   805        /* avoid buffer * overrun */
   806        maxout = (int64_t)destsize - (int64_t)ntbytes;
   807        if (maxout <= 0) {
   808          return 0;                  /* non-compressible block */
   809        }
   810      }
   811      if (dict_training) {
   812        // We are in the build dict state, so don't compress
   813        // TODO: copy only a percentage for sampling
   814        memcpy(dest, _src + j * neblock, (unsigned int)neblock);
   815        cbytes = (int32_t)neblock;
   816      }
   817      else if (context->compcode == BLOSC_BLOSCLZ) {
   818        cbytes = blosclz_compress(context->clevel, _src + j * neblock,
   819                                  (int)neblock, dest, (int)maxout);
   820      }
   821    #if defined(HAVE_LZ4)
   822      else if (context->compcode == BLOSC_LZ4) {
   823        void *hash_table = NULL;
   824      #ifdef HAVE_IPP
   825        hash_table = (void*)thread_context->lz4_hash_table;
   826      #endif
   827        cbytes = lz4_wrap_compress((char*)_src + j * neblock, (size_t)neblock,
   828                                   (char*)dest, (size_t)maxout, accel, hash_table);
   829      }
   830      else if (context->compcode == BLOSC_LZ4HC) {
   831        cbytes = lz4hc_wrap_compress((char*)_src + j * neblock, (size_t)neblock,
   832                                     (char*)dest, (size_t)maxout, context->clevel);
   833      }
   834    #endif /* HAVE_LZ4 */
   835    #if defined(HAVE_LIZARD)
   836      else if (context->compcode == BLOSC_LIZARD) {
   837        cbytes = lizard_wrap_compress((char*)_src + j * neblock, (size_t)neblock,
   838                                      (char*)dest, (size_t)maxout, accel);
   839      }
   840    #endif /* HAVE_LIZARD */
   841    #if defined(HAVE_SNAPPY)
   842      else if (context->compcode == BLOSC_SNAPPY) {
   843        cbytes = snappy_wrap_compress((char*)_src + j * neblock, (size_t)neblock,
   844                                      (char*)dest, (size_t)maxout);
   845      }
   846    #endif /* HAVE_SNAPPY */
   847    #if defined(HAVE_ZLIB)
   848      else if (context->compcode == BLOSC_ZLIB) {
   849        cbytes = zlib_wrap_compress((char*)_src + j * neblock, (size_t)neblock,
   850                                    (char*)dest, (size_t)maxout, context->clevel);
   851      }
   852    #endif /* HAVE_ZLIB */
   853    #if defined(HAVE_ZSTD)
   854      else if (context->compcode == BLOSC_ZSTD) {
   855        cbytes = zstd_wrap_compress(thread_context,
   856                                    (char*)_src + j * neblock, (size_t)neblock,
   857                                    (char*)dest, (size_t)maxout, context->clevel);
   858      }
   859    #endif /* HAVE_ZSTD */
   860
   861      else {
   862        blosc_compcode_to_compname(context->compcode, &compname);
   863        BLOSC_TRACE_ERROR("Blosc has not been compiled with '%s' compression support."
   864                          "Please use one having it.", compname);
   865        return -5;    /* signals no compression support */
   866      }
   867
   868      if (cbytes > maxout) {
   869        /* Buffer overrun caused by compression (should never happen) */
   870        return -1;
   871      }
   872      if (cbytes < 0) {
   873        /* cbytes should never be negative */
   874        return -2;
   875      }
   876      if (!dict_training) {
   877        if (cbytes == 0 || cbytes == neblock) {
   878          /* The compressor has been unable to compress data at all. */
   879          /* Before doing the copy, check that we are not running into a
   880             buffer overflow. */
   881          if ((ntbytes + neblock) > destsize) {
   882            return 0;    /* Non-compressible data */
   883          }
   884          memcpy(dest, _src + j * neblock, (unsigned int)neblock);
   885          cbytes = neblock;
   886        }
   887        _sw32(dest - 4, cbytes);
   888      }
   889      dest += cbytes;
   890      ntbytes += cbytes;
   891      ctbytes += cbytes;
   892    }  /* Closes j < nstreams */
   893
   894    //printf("c%d", ctbytes);
   895    return ctbytes;
   896  }
