   984  /* Decompress & unshuffle a single block */
   985  static int blosc_d(
   986      struct thread_context* thread_context, int32_t bsize,
   987      int32_t leftoverblock, const uint8_t* src, int32_t srcsize, int32_t src_offset,
   988      int32_t nblock, uint8_t* dest, int32_t dest_offset, uint8_t* tmp, uint8_t* tmp2) {
   989    blosc2_context* context = thread_context->parent_context;
   990    uint8_t* filters = context->filters;
   991    uint8_t *tmp3 = thread_context->tmp4;
   992    int32_t compformat = (context->header_flags & (uint8_t)0xe0) >> 5u;
   993    int dont_split = (context->header_flags & (uint8_t)0x10) >> 4u;
   994    //uint8_t blosc_version_format = src[BLOSC2_CHUNK_VERSION];
   995    int nstreams;
   996    int32_t neblock;
   997    int32_t nbytes;                /* number of decompressed bytes in split */
   998    int32_t cbytes;                /* number of compressed bytes in split */
   999    int32_t ctbytes = 0;           /* number of compressed bytes in block */
  1000    int32_t ntbytes = 0;           /* number of uncompressed bytes in block */
  1001    uint8_t* _dest;
  1002    int32_t typesize = context->typesize;
  1003    const char* compname;
  1004
  1005    if (context->block_maskout != NULL && context->block_maskout[nblock]) {
  1006      // Do not decompress, but act as if we successfully decompressed everything
  1007      return bsize;
  1008    }
  1009
  1010    bool is_lazy = context->blosc2_flags & 0x08u;
  1011    if (is_lazy) {
  1012      // The chunk is on disk, so just lazily load the block
  1013      if (context->schunk == NULL) {
  1014        BLOSC_TRACE_ERROR("Lazy chunk needs an associated super-chunk.");
  1015        return -11;
  1016      }
  1017      if (context->schunk->frame == NULL) {
  1018        BLOSC_TRACE_ERROR("Lazy chunk needs an associated frame.");
  1019        return -12;
  1020      }
  1021      char *fname = context->schunk->frame->fname;
  1022      int32_t trailer_len = sizeof(int32_t) + sizeof(int64_t) + context->nblocks * sizeof(int32_t);
  1023      int32_t non_lazy_chunklen = srcsize - trailer_len;
  1024      // The offset of the actual chunk is in the trailer
  1025      int64_t chunk_offset = *(int64_t*)(src + non_lazy_chunklen + sizeof(int32_t));
  1026      // Get the csize of the nblock
  1027      int32_t *block_csizes = (int32_t *)(src + non_lazy_chunklen + sizeof(int32_t) + sizeof(int64_t));
  1028      int32_t block_csize = block_csizes[nblock];
  1029      // Read the lazy block on disk
  1030      FILE* fp = fopen(fname, "rb");
  1031      // The offset of the block is src_offset
  1032      fseek(fp, chunk_offset + src_offset, SEEK_SET);
  1033      size_t rbytes = fread((void*)(src + src_offset), 1, block_csize, fp);
  1034      fclose(fp);
  1035      if (rbytes != block_csize) {
  1036        BLOSC_TRACE_ERROR("Cannot read the (lazy) block out of the fileframe.");
  1037        return -13;
  1038      }
  1039    }
  1040
  1041    // If the chunk is memcpyed, we just have to copy the block to dest and return
  1042    int memcpyed = src[BLOSC2_CHUNK_FLAGS] & (uint8_t)BLOSC_MEMCPYED;
  1043    if (memcpyed) {
  1044      int32_t chunk_nbytes = *(int32_t*)(src + BLOSC2_CHUNK_NBYTES);
  1045      int32_t chunk_cbytes = *(int32_t*)(src + BLOSC2_CHUNK_CBYTES);
  1046      if (chunk_nbytes + BLOSC_MAX_OVERHEAD != chunk_cbytes) {
  1047        return -1;
  1048      }
  1049      int bsize_ = leftoverblock ? chunk_nbytes % context->blocksize : bsize;
  1050      if (chunk_cbytes < BLOSC_MAX_OVERHEAD + (nblock * context->blocksize) + bsize_) {
  1051        /* Not enough input to copy block */
  1052        return -1;
  1053      }
  1054      memcpy(dest + dest_offset, src + BLOSC_MAX_OVERHEAD + nblock * context->blocksize, bsize_);
  1055      return bsize_;
  1056    }
  1057
  1058    if (src_offset <= 0 || src_offset >= srcsize) {
  1059      /* Invalid block src offset encountered */
  1060      return -1;
  1061    }
  1062
  1063    src += src_offset;
  1064    srcsize -= src_offset;
  1065
  1066    int last_filter_index = last_filter(filters, 'd');
  1067
  1068    if ((last_filter_index >= 0) &&
  1069            (next_filter(filters, BLOSC2_MAX_FILTERS, 'd') != BLOSC_DELTA)) {
  1070     // We are making use of some filter, so use a temp for destination
  1071     _dest = tmp;
  1072    } else {
  1073      // If no filters, or only DELTA in pipeline
  1074     _dest = dest + dest_offset;
  1075    }
  1076
  1077    /* The number of compressed data streams for this block */
  1078    if (!dont_split && !leftoverblock && !context->use_dict) {
  1079      // We don't want to split when in a training dict state
  1080      nstreams = (int32_t)typesize;
  1081    }
  1082    else {
  1083      nstreams = 1;
  1084    }
  1085
  1086    neblock = bsize / nstreams;
  1087    for (int j = 0; j < nstreams; j++) {
  1088      if (srcsize < sizeof(int32_t)) {
  1089        /* Not enough input to read compressed size */
  1090        return -1;
  1091      }
  1092      srcsize -= sizeof(int32_t);
  1093      cbytes = sw32_(src);      /* amount of compressed bytes */
  1094      if (cbytes > 0) {
  1095        if (srcsize < cbytes) {
  1096          /* Not enough input to read compressed bytes */
  1097          return -1;
  1098        }
  1099        srcsize -= cbytes;
  1100      }
  1101      src += sizeof(int32_t);
  1102      ctbytes += (int32_t)sizeof(int32_t);
  1103
  1104      /* Uncompress */
  1105      if (cbytes == 0) {
  1106        // A run of 0's
  1107        memset(_dest, 0, (unsigned int)neblock);
  1108        nbytes = neblock;
  1109      }
  1110      else if (cbytes < 0) {
  1111        // A negative number means some encoding depending on the token that comes next
  1112        uint8_t token = src[0];
  1113        src += 1;
  1114        ctbytes += 1;
  1115        if (token & 0x1) {
  1116          // A run of bytes that are different than 0
  1117          if (cbytes < -255) {
  1118            // Runs can only encode a byte
  1119            return -2;
  1120          }
  1121          uint8_t value = -cbytes;
  1122          memset(_dest, value, (unsigned int) neblock);
  1123          nbytes = neblock;
  1124          cbytes = 0;  // everything is encoded in the cbytes token
  1125        }
  1126      }
  1127      else if (cbytes == neblock) {
  1128        memcpy(_dest, src, (unsigned int)neblock);
  1129        nbytes = (int32_t)neblock;
  1130      }
  1131      else {
  1132        if (compformat == BLOSC_BLOSCLZ_FORMAT) {
  1133          nbytes = blosclz_decompress(src, cbytes, _dest, (int)neblock);
  1134        }
  1135    #if defined(HAVE_LZ4)
  1136        else if (compformat == BLOSC_LZ4_FORMAT) {
  1137          nbytes = lz4_wrap_decompress((char*)src, (size_t)cbytes,
  1138                                       (char*)_dest, (size_t)neblock);
  1139        }
  1140    #endif /*  HAVE_LZ4 */
  1141    #if defined(HAVE_LIZARD)
  1142        else if (compformat == BLOSC_LIZARD_FORMAT) {
  1143          nbytes = lizard_wrap_decompress((char*)src, (size_t)cbytes,
  1144                                          (char*)_dest, (size_t)neblock);
  1145        }
  1146    #endif /*  HAVE_LIZARD */
  1147    #if defined(HAVE_SNAPPY)
  1148        else if (compformat == BLOSC_SNAPPY_FORMAT) {
  1149          nbytes = snappy_wrap_decompress((char*)src, (size_t)cbytes,
  1150                                          (char*)_dest, (size_t)neblock);
  1151        }
  1152    #endif /*  HAVE_SNAPPY */
  1153    #if defined(HAVE_ZLIB)
  1154        else if (compformat == BLOSC_ZLIB_FORMAT) {
  1155          nbytes = zlib_wrap_decompress((char*)src, (size_t)cbytes,
  1156                                        (char*)_dest, (size_t)neblock);
  1157        }
  1158    #endif /*  HAVE_ZLIB */
  1159    #if defined(HAVE_ZSTD)
  1160        else if (compformat == BLOSC_ZSTD_FORMAT) {
  1161          nbytes = zstd_wrap_decompress(thread_context,
  1162                                        (char*)src, (size_t)cbytes,
  1163                                        (char*)_dest, (size_t)neblock);
  1164        }
  1165    #endif /*  HAVE_ZSTD */
  1166        else {
  1167          compname = clibcode_to_clibname(compformat);
  1168          BLOSC_TRACE_ERROR(
  1169                  "Blosc has not been compiled with decompression "
  1170                  "support for '%s' format.  "
  1171                  "Please recompile for adding this support.", compname);
  1172          return -5;    /* signals no decompression support */
  1173        }
  1174
  1175        /* Check that decompressed bytes number is correct */
  1176        if (nbytes != neblock) {
  1177          return -2;
  1178        }
  1179
  1180      }
  2190
  2191    assert(ntbytes <= (int32_t)destsize);
  2192    return ntbytes;
  2193  }
